/**
 * Rich Menu definition: 2500x1686 = a plan status bar on top + 4 columns x 2 rows of tiles.
 *
 * There is one menu per plan variant (free / trial / plus / pro): same tiles, different status bar,
 * so the user always sees which plan they are on and a "สมัคร / อัปเกรด" button. Each user is linked
 * to their variant (see rich-menu-sync.ts); the free variant is the channel default.
 *
 * The images are generated by scripts/build-rich-menu.ts from the same TILES/BAR lists, so labels
 * and tap areas can never drift apart.
 */
import type { MascotExpression } from '../mascot.ts';
import { encodePostback, type ActionName } from '../postback.ts';

export const RICH_MENU_SIZE = { width: 2500, height: 1686 } as const;
export const BAR_HEIGHT = 330;
export const RICH_MENU_PREFIX = 'ShikSheek v2';

export type RichMenuVariant = 'free' | 'trial' | 'plus' | 'pro';
export const RICH_MENU_VARIANTS: readonly RichMenuVariant[] = ['free', 'trial', 'plus', 'pro'];
/** LINE rich menu alias per variant (aliases let the bot find menu ids without a database). */
export const richMenuAlias = (v: RichMenuVariant) => `shiksheek-${v}`;

export interface RichMenuTile {
  labelTh: string;
  labelEn: string;
  mascot: MascotExpression;
  theme: 'red' | 'yellow' | 'white' | 'deepRed';
  /** open a LIFF tab directly … */
  liffTab?: 'home' | 'txns' | 'settings';
  /** … or send a postback */
  action?: ActionName;
  displayText?: string;
  openKeyboard?: boolean;
}

/** Order = left→right, top→bottom (4 per row). */
export const TILES: readonly RichMenuTile[] = [
  { labelTh: 'ภาพรวม', labelEn: 'DASHBOARD', mascot: 'encouraging', theme: 'red', liffTab: 'home' },
  { labelTh: 'จดรายจ่าย', labelEn: 'EXPENSE', mascot: 'worried', theme: 'yellow', action: 'add_expense', displayText: 'จดรายจ่าย', openKeyboard: true },
  { labelTh: 'จดรายรับ', labelEn: 'INCOME', mascot: 'saving', theme: 'white', action: 'add_income', displayText: 'จดรายรับ', openKeyboard: true },
  { labelTh: 'รายการ', labelEn: 'HISTORY', mascot: 'thinking', theme: 'white', liffTab: 'txns' },
  { labelTh: 'บิลประจำ', labelEn: 'BILLS', mascot: 'discipline', theme: 'white', action: 'fixed_costs', displayText: 'ค่าใช้จ่ายประจำ' },
  { labelTh: 'งบ & เป้าออม', labelEn: 'BUDGETS', mascot: 'smart', theme: 'white', action: 'budgets', displayText: 'งบประมาณ' },
  { labelTh: 'รายงาน', labelEn: 'REPORTS', mascot: 'planning', theme: 'deepRed', action: 'reports', displayText: 'รายงาน' },
  { labelTh: 'ตั้งค่า', labelEn: 'SETTINGS', mascot: 'sleepy', theme: 'white', liffTab: 'settings' },
];

/** Status bar copy per variant. */
export const BAR: Record<RichMenuVariant, { kicker: string; plan: string; cta: string; mascot: MascotExpression; tone: 'cream' | 'violet' | 'red' }> = {
  free: { kicker: 'แพ็กเกจของคุณ', plan: 'ฟรี', cta: 'อัปเกรด ✨', mascot: 'excited', tone: 'cream' },
  trial: { kicker: 'กำลังทดลองใช้', plan: 'Pro ฟรี 14 วัน', cta: 'สมัครเลย', mascot: 'celebrating', tone: 'violet' },
  plus: { kicker: 'แพ็กเกจของคุณ', plan: 'ชิกชิก Plus', cta: 'แพ็กเกจของฉัน', mascot: 'proud', tone: 'red' },
  pro: { kicker: 'แพ็กเกจของคุณ', plan: 'ชิกชิก Pro', cta: 'แพ็กเกจของฉัน', mascot: 'proud', tone: 'violet' },
};

const COLS = 4;
export function tileBounds(index: number) {
  const col = index % COLS;
  const r = Math.floor(index / COLS);
  const xs = [0, 625, 1250, 1875, 2500];
  const rowH = (RICH_MENU_SIZE.height - BAR_HEIGHT) / 2; // 678
  const top = BAR_HEIGHT + r * rowH;
  return { x: xs[col]!, y: Math.round(top), width: xs[col + 1]! - xs[col]!, height: Math.round(rowH) };
}

export function richMenuDefinition(variant: RichMenuVariant, liffUrl: string) {
  const base = liffUrl.replace(/\/+$/, '');
  return {
    size: RICH_MENU_SIZE,
    selected: true,
    name: `${RICH_MENU_PREFIX} ${variant}`,
    chatBarText: 'เมนูชิกชิก 🐔',
    areas: [
      // the whole status bar opens "แพ็กเกจของฉัน" (status + Plus/Pro buy buttons)
      {
        bounds: { x: 0, y: 0, width: RICH_MENU_SIZE.width, height: BAR_HEIGHT },
        action: { type: 'postback', label: 'แพ็กเกจ', data: encodePostback('plans'), displayText: 'แพ็กเกจของฉัน' },
      },
      ...TILES.map((t, i) => ({
        bounds: tileBounds(i),
        action: t.liffTab
          ? { type: 'uri', label: t.labelTh, uri: `${base}?tab=${t.liffTab}` }
          : {
              type: 'postback',
              label: t.labelTh,
              data: encodePostback(t.action!),
              ...(t.displayText ? { displayText: t.displayText } : {}),
              ...(t.openKeyboard ? { inputOption: 'openKeyboard' } : {}),
            },
      })),
    ],
  };
}
